package dev.androiduse;

import java.util.*;
import org.codehaus.janino.SimpleCompiler;

/** Compile Java in the isolated process. Generated bytecode is checked before loading. */
final class SandboxEngine {
 static final int MAX_CODE=32768,MAX_INPUT=16384,MAX_OBSERVATION=131072,MAX_STATE=8192,MAX_OUTPUT=65536,MAX_LOG=8192;
 static final long MAX_MILLIS=2000,MAX_BUILD_MILLIS=8000;
 interface Loader {Class<?> load(Map<String,byte[]> bytecodes)throws Exception;}
 static Map<String,byte[]> compile(String code)throws Exception{
  if(code==null||code.isEmpty()||code.length()>MAX_CODE)throw new IllegalArgumentException("Java source limit exceeded");
  String source="package dev.androiduse.generated; import org.json.*; import java.util.*; public final class GoalProgram { public static Object run(dev.androiduse.SandboxApi ctx) throws Exception {\n"+code+"\n}}";
  SimpleCompiler compiler=new SimpleCompiler();compiler.setParentClassLoader(SandboxEngine.class.getClassLoader());compiler.setSourceVersion(8);compiler.setTargetVersion(8);compiler.cook("GoalProgram.java",source);
  Map<String,byte[]> bytecodes=compiler.getBytecodes();JavaBytecodePolicy.check(bytecodes);return bytecodes;
 }
 static String run(String code,String input,String observation,String state,Loader loader,Runnable beforeExecution)throws Exception{
  if(input.length()>MAX_INPUT||observation.length()>MAX_OBSERVATION||state.length()>MAX_STATE)throw new IllegalArgumentException("Sandbox input limit exceeded");
  SandboxApi api=new SandboxApi(input,observation,state);Map<String,byte[]> bytes=compile(code);Class<?> program=loader.load(bytes);beforeExecution.run();
  try{Object result=program.getMethod("run",SandboxApi.class).invoke(null,api);return api.finish(result);}catch(java.lang.reflect.InvocationTargetException e){Throwable error=e.getCause();if(error instanceof Exception)throw (Exception)error;throw e;}
 }
 private SandboxEngine(){}
}
